using System;using System.Reflection;using System.Drawing;using System.Windows.Forms;using System.Linq;
class Smoke{
 [STAThread]static void Main(){Application.EnableVisualStyles();var a=Assembly.LoadFrom("LeviAfan-Zapret.exe");var type=a.GetType("MainForm");var f=(Form)Activator.CreateInstance(type,true);foreach(string n in new[]{"autoStart","startTray"})((CheckBox)type.GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f)).Checked=false;f.Show();Application.DoEvents();var tabs=f.Controls.OfType<TabControl>().Single();
 foreach(var size in new[]{new Size(1040,760),new Size(780,600)}){f.Size=size;foreach(int index in new[]{0,1}){tabs.SelectedIndex=index;Application.DoEvents();if(index==1){var page=tabs.SelectedTab;var panel=page.Controls.OfType<TableLayoutPanel>().Single();var grid=panel.Controls.OfType<TableLayoutPanel>().First();if(grid.Controls.OfType<Button>().Count()!=13)throw new Exception("Missing tool buttons");foreach(var b in grid.Controls.OfType<Button>()){if(!grid.ClientRectangle.Contains(b.Bounds))throw new Exception("Clipped tool: "+b.Text);var bounds=new Rectangle(page.PointToClient(b.PointToScreen(Point.Empty)),b.Size);if(!page.ClientRectangle.Contains(bounds))throw new Exception("Tool outside page: "+b.Text);}var input=panel.Controls.OfType<TableLayoutPanel>().Last();if(!panel.ClientRectangle.Contains(input.Bounds))throw new Exception("Input clipped");var log=panel.Controls.OfType<TextBox>().Single();if(log.Height<80)throw new Exception("Log too small");Console.WriteLine("PASS: 13 tool buttons, input and log fit at "+size);}
 using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(Point.Empty,f.Size));bitmap.Save("gui/preview-"+index+"-"+size.Width+".png");}}}f.Dispose();}
}
